// FROZEN CONTRACT for Rack to the Future. Owned by the main session.
// Builders import from here and code against it. Do not edit this file.
//
// The app is one shared data model (scenario -> engine -> metrics) drawn at seven scales.
// Module 1 (Business): fleet, site, offworld levels + the business panel.
// Module 2 (Engineering): chip, rack, hall, building levels.

/** Zoom ladder, finest to coarsest. Picking an object zooms one step finer. */
export const LEVELS = ['chip', 'rack', 'hall', 'building', 'site', 'fleet', 'offworld'];

export const LEVEL_TITLES = {
  chip: 'Chip', rack: 'Rack', hall: 'Hall', building: 'Building',
  site: 'Site', fleet: 'Earth fleet', offworld: 'Off-world',
};

export const MODULES = {
  business: ['fleet', 'site', 'offworld'],
  engineering: ['chip', 'rack', 'hall', 'building'],
};

/** Off-world sites skip building and hall: site -> rack -> chip. */
export const OFFWORLD_KINDS = ['leo', 'moon', 'mars'];

/** Lenses recolour every level without moving the camera. */
export const LENSES = ['heat', 'power', 'cost', 'sentiment', 'water'];
export const LENS_TITLES = { heat: 'Heat', power: 'Power', cost: 'Cost', sentiment: 'Sentiment', water: 'Water' };

/** Constraint checks, in the order the "first failing" banner reads them. */
